	return fmt.Sprintf("%v (checkpoint ref recovery failed: %v)", e.pushErr, e.recoveryErr)
}

func (e *checkpointRefRecoveryError) Unwrap() []error {
	return []error{e.pushErr, e.recoveryErr}
