package checkpoint

import (
	"context"
	"errors"
	"fmt"
	"path"
	"slices"

	"github.com/go-git/go-git/v6"
	"github.com/go-git/go-git/v6/plumbing"
	"github.com/go-git/go-git/v6/plumbing/filemode"
	"github.com/go-git/go-git/v6/plumbing/object"
)

// ErrReplayConflict identifies incompatible changes to the same checkpoint data.
var ErrReplayConflict = errors.New("checkpoint replay content conflict")

// ReplayTrees replays a tree change against the current target. Sessions are
// matched by identity, while incompatible changes to the same data are refused.
func ReplayTrees(ctx context.Context, repo *git.Repository, before, after, onto plumbing.Hash) (plumbing.Hash, error) {
	return mergeReplayTrees(ctx, repo, before, after, onto, "")
}

// mergeReplayTrees applies the change from before to after onto the target tree. Equal
// subtrees are reused; only directories changed on both sides need traversal.
// Files are compared by hash and mode, never merged by their textual contents.
// A zero hash represents an absent directory (including a root commit's parent).
func mergeReplayTrees(ctx context.Context, repo *git.Repository, before, after, onto plumbing.Hash, prefix string) (plumbing.Hash, error) {
	if err := ctx.Err(); err != nil {
		return plumbing.ZeroHash, err //nolint:wrapcheck // preserve context cancellation
	}
	if before == after || after == onto {
		return onto, nil
	}
	if before == onto {
		return after, nil
	}

	base, err := replayTreeEntries(repo, before)
	if err != nil {
		return plumbing.ZeroHash, err
	}
	local, err := replayTreeEntries(repo, after)
	if err != nil {
		return plumbing.ZeroHash, err
	}
	remote, err := replayTreeEntries(repo, onto)
	if err != nil {
		return plumbing.ZeroHash, err
	}

	if merged, handled, mergeErr := mergeCheckpointSessions(ctx, repo, base, local, remote, prefix); handled || mergeErr != nil {
		return merged, mergeErr
	}
	return mergeReplayEntries(ctx, repo, base, local, remote, onto, prefix)
}

func mergeReplayEntries(ctx context.Context, repo *git.Repository, base, local, remote map[string]object.TreeEntry, onto plumbing.Hash, prefix string) (plumbing.Hash, error) {
	// Sort the union so a conflict reports the same path on every retry.
	names := make([]string, 0, len(base)+len(local))
	for name := range base {
		names = append(names, name)
	}
	for name := range local {
		if _, exists := base[name]; !exists {
			names = append(names, name)
		}
	}
	slices.Sort(names)
	changes := make([]TreeChange, 0, len(names))
	for _, name := range names {
		merged, mergeErr := mergeReplayEntry(ctx, repo, base[name], local[name], remote[name], path.Join(prefix, name))
		if mergeErr != nil {
			return plumbing.ZeroHash, mergeErr
		}
		if merged == remote[name] {
			continue
		}
		change := TreeChange{Path: name}
		if merged.Mode != 0 {
			change.Entry = &merged
		}
		changes = append(changes, change)
	}
	merged, err := ApplyTreeChanges(ctx, repo, onto, changes)
	if err != nil {
		return plumbing.ZeroHash, fmt.Errorf("apply replay changes: %w", err)
	}
	return merged, nil
}

func mergeReplayEntry(ctx context.Context, repo *git.Repository, before, after, onto object.TreeEntry, name string) (object.TreeEntry, error) {
	switch {
	case after == before, after == onto:
		return onto, nil
	case onto == before:
		return after, nil
	}
	if merged, handled, err := mergeReplaySessionMetadata(repo, before, after, onto, name); handled || err != nil {
		return merged, err
	}
	// Both sides changed this entry. Directories can contain independent changes,
	// but a changed blob, mode or file/directory boundary is a conflict.
	for _, entry := range []object.TreeEntry{before, after, onto} {
		if entry.Mode != 0 && entry.Mode != filemode.Dir {
			return object.TreeEntry{}, fmt.Errorf("%w at %q", ErrReplayConflict, name)
		}
	}
	hash, err := mergeReplayTrees(ctx, repo, before.Hash, after.Hash, onto.Hash, name)
	if err != nil {
		return object.TreeEntry{}, err
	}
	return object.TreeEntry{Name: path.Base(name), Mode: filemode.Dir, Hash: hash}, nil
}

func replayTreeEntries(repo *git.Repository, hash plumbing.Hash) (map[string]object.TreeEntry, error) {
	entries := make(map[string]object.TreeEntry)
	if hash.IsZero() {
		return entries, nil
	}
	tree, err := repo.TreeObject(hash)
	if err != nil {
		return nil, fmt.Errorf("read replay tree %s: %w", hash, err)
	}
	for _, entry := range tree.Entries {
		entries[entry.Name] = entry
	}
	return entries, nil
}
package checkpoint

import (
	"bytes"
	"encoding/json"
	"fmt"
	"maps"
	"path"
	"slices"

	"github.com/entireio/cli/cmd/entire/cli/jsonutil"
	"github.com/entireio/cli/cmd/entire/cli/paths"
	"github.com/go-git/go-git/v6"
	"github.com/go-git/go-git/v6/plumbing/object"
)

// mergeReplayJSON preserves unknown fields and JSON number precision. Only
// independent or identical field changes are accepted; conflicting values refuse
// the replay instead of choosing a writer or merging opaque arrays.
func mergeReplayJSON(base, local, remote map[string]json.RawMessage, name string) (map[string]json.RawMessage, error) {
	out := maps.Clone(remote)
	if out == nil {
		out = make(map[string]json.RawMessage)
	}
	keys := maps.Clone(base)
	if keys == nil {
		keys = make(map[string]json.RawMessage)
	}
	maps.Copy(keys, local)
	for _, key := range slices.Sorted(maps.Keys(keys)) {
		before, after, onto := base[key], local[key], remote[key]
		switch {
		case replayJSONEqual(after, before), replayJSONEqual(after, onto):
			continue
		case !replayJSONEqual(before, onto):
			return nil, fmt.Errorf("%w at %q field %q", ErrReplayConflict, name, key)
		}
		if after == nil {
			delete(out, key)
		} else {
			out[key] = after
		}
	}
	return out, nil
}

func replayJSONEqual(a, b json.RawMessage) bool {
	if bytes.Equal(a, b) {
		return true
	}
	canonical := func(raw json.RawMessage) ([]byte, error) {
		decoder := json.NewDecoder(bytes.NewReader(raw))
		decoder.UseNumber()
		var value any
		if err := decoder.Decode(&value); err != nil {
			return nil, fmt.Errorf("decode replay JSON: %w", err)
		}
		return json.Marshal(value)
	}
	left, leftErr := canonical(a)
	right, rightErr := canonical(b)
	return leftErr == nil && rightErr == nil && bytes.Equal(left, right)
}

// Session metadata can change independently of its transcript (for example a
// generated summary). Merge independent fields without decoding opaque values.
//
//nolint:nilerr // Optional schema probe: non-session JSON uses ordinary entry conflict detection.
func mergeReplaySessionMetadata(repo *git.Repository, base, local, remote object.TreeEntry, name string) (object.TreeEntry, bool, error) {
	if path.Base(name) != paths.MetadataFileName || !local.Mode.IsRegular() || !remote.Mode.IsRegular() {
		return object.TreeEntry{}, false, nil
	}
	if local.Mode != remote.Mode || (base.Mode != 0 && base.Mode != local.Mode) {
		return object.TreeEntry{}, false, nil
	}
	left, leftErr := readJSONFromBlob[Metadata](repo, local.Hash)
	right, rightErr := readJSONFromBlob[Metadata](repo, remote.Hash)
	if leftErr != nil || rightErr != nil || left.SessionID == "" || left.SessionID != right.SessionID || left.CheckpointID != right.CheckpointID {
		return object.TreeEntry{}, false, nil
	}
	read := func(entry object.TreeEntry) (map[string]json.RawMessage, error) {
		if entry.Mode == 0 {
			return map[string]json.RawMessage{}, nil
		}
		fields, err := readJSONFromBlob[map[string]json.RawMessage](repo, entry.Hash)
		if err != nil {
			return nil, err
		}
		return *fields, nil
	}
	before, err := read(base)
	if err != nil {
		return object.TreeEntry{}, true, err
	}
	after, err := read(local)
	if err != nil {
		return object.TreeEntry{}, true, err
	}
	onto, err := read(remote)
	if err != nil {
		return object.TreeEntry{}, true, err
	}
	fields, err := mergeReplayJSON(before, after, onto, name)
	if err != nil {
		return object.TreeEntry{}, true, err
	}
	if replayJSONObjectEqual(fields, onto) {
		return remote, true, nil
	}
	data, err := jsonutil.MarshalIndentWithNewline(fields, "", "  ")
	if err != nil {
		return object.TreeEntry{}, true, fmt.Errorf("encode replay metadata: %w", err)
	}
	hash, err := CreateBlobFromContent(repo, data)
	if err != nil {
		return object.TreeEntry{}, true, err
	}
	return object.TreeEntry{Name: local.Name, Mode: local.Mode, Hash: hash}, true, nil
}

func replayJSONObjectEqual(a, b map[string]json.RawMessage) bool {
	if len(a) != len(b) {
		return false
	}
	for key, value := range a {
		if !replayJSONEqual(value, b[key]) {
			return false
		}
	}
	return true
}

package checkpoint

import (
	"context"
	"encoding/json"
	"fmt"
	"maps"
	"path"
	"slices"
	"strconv"
	"strings"

	"github.com/entireio/cli/cmd/entire/cli/jsonutil"
	"github.com/entireio/cli/cmd/entire/cli/paths"
	"github.com/entireio/cli/cmd/entire/cli/versioninfo"
	"github.com/go-git/go-git/v6"
	"github.com/go-git/go-git/v6/plumbing"
	"github.com/go-git/go-git/v6/plumbing/filemode"
	"github.com/go-git/go-git/v6/plumbing/object"
)

type replaySession struct {
	tree   plumbing.Hash
	fields map[string]json.RawMessage
}

type replayCheckpoint struct {
	metadata plumbing.Hash
	summary  *CheckpointSummary
	fields   map[string]json.RawMessage
	sessions map[string]replaySession
	order    []string
	extra    map[string]object.TreeEntry
}

// mergeCheckpointSessions handles actual checkpoint roots, including roots nested
// under the v1 branch. Numeric slots are storage locations, not session identity.
func mergeCheckpointSessions(ctx context.Context, repo *git.Repository, base, local, remote map[string]object.TreeEntry, prefix string) (plumbing.Hash, bool, error) {
	left, err := loadReplayCheckpoint(repo, local, prefix)
	if err != nil || left == nil {
		return plumbing.ZeroHash, false, err
	}
	right, err := loadReplayCheckpoint(repo, remote, prefix)
	if err != nil || right == nil {
		return plumbing.ZeroHash, false, err
	}
	original, err := loadReplayCheckpoint(repo, base, prefix)
	if err != nil {
		return plumbing.ZeroHash, true, err
	}
	if original == nil {
		if _, exists := base[paths.MetadataFileName]; exists {
			return plumbing.ZeroHash, true, fmt.Errorf("%w: invalid checkpoint preimage at %q", ErrReplayConflict, prefix)
		}
		original = &replayCheckpoint{fields: map[string]json.RawMessage{}, extra: base, sessions: map[string]replaySession{}}
	}
	if left.summary.CheckpointID != right.summary.CheckpointID || (original.summary != nil && original.summary.CheckpointID != left.summary.CheckpointID) {
		return plumbing.ZeroHash, true, fmt.Errorf("%w: checkpoint identity changed at %q", ErrReplayConflict, prefix)
	}
	merged, err := mergeReplayCheckpoint(ctx, repo, original, left, right, prefix)
	return merged, true, err
}

//nolint:nilnil,nilerr // Optional schema probe: other trees also contain metadata.json; a non-checkpoint falls back to entry-level replay.
func loadReplayCheckpoint(repo *git.Repository, entries map[string]object.TreeEntry, prefix string) (*replayCheckpoint, error) {
	metadata, exists := entries[paths.MetadataFileName]
	if !exists || !metadata.Mode.IsFile() {
		return nil, nil
	}
	summary, err := readJSONFromBlob[CheckpointSummary](repo, metadata.Hash)
	if err != nil || summary.CheckpointID.IsEmpty() || summary.Sessions == nil {
		return nil, nil // An ordinary tree or per-session metadata, not a checkpoint root.
	}
	fields, err := readJSONFromBlob[map[string]json.RawMessage](repo, metadata.Hash)
	if err != nil {
		return nil, err
	}
	var sessionFields []map[string]json.RawMessage
	if err := json.Unmarshal((*fields)["sessions"], &sessionFields); err != nil {
		return nil, fmt.Errorf("read replay session paths: %w", err)
	}
	cp := &replayCheckpoint{metadata: metadata.Hash, summary: summary, fields: *fields, sessions: make(map[string]replaySession), extra: maps.Clone(entries)}
	delete(cp.extra, paths.MetadataFileName)
	for index := range summary.Sessions {
		name := strconv.Itoa(index)
		entry := entries[name]
		if entry.Mode != filemode.Dir {
			return nil, fmt.Errorf("%w: missing session directory %q", ErrReplayConflict, path.Join(prefix, name))
		}
		sessionTree, treeErr := repo.TreeObject(entry.Hash)
		if treeErr != nil {
			return nil, fmt.Errorf("read replay session tree: %w", treeErr)
		}
		metaEntry, findErr := sessionTree.FindEntry(paths.MetadataFileName)
		if findErr != nil {
			return nil, fmt.Errorf("read replay session metadata: %w", findErr)
		}
		meta, readErr := readJSONFromBlob[Metadata](repo, metaEntry.Hash)
		if readErr != nil {
			return nil, readErr
		}
		if meta.SessionID == "" || meta.CheckpointID != summary.CheckpointID {
			return nil, fmt.Errorf("%w: invalid session identity in %q", ErrReplayConflict, path.Join(prefix, name))
		}
		if _, duplicate := cp.sessions[meta.SessionID]; duplicate {
			return nil, fmt.Errorf("%w: duplicate session %q", ErrReplayConflict, meta.SessionID)
		}
		normalized, normalizeErr := replaySessionPaths(sessionFields[index], "/"+path.Join(prefix, name)+"/", "/")
		if normalizeErr != nil {
			return nil, normalizeErr
		}
		if string(normalized["metadata"]) != `"/metadata.json"` {
			return nil, fmt.Errorf("%w: invalid session metadata path", ErrReplayConflict)
		}
		cp.sessions[meta.SessionID] = replaySession{tree: entry.Hash, fields: normalized}
		cp.order = append(cp.order, meta.SessionID)
		delete(cp.extra, name)
	}
	for name := range cp.extra {
		if _, numeric := strconv.Atoi(name); numeric == nil {
			return nil, fmt.Errorf("%w: unlisted session slot %q", ErrReplayConflict, name)
		}
	}
	return cp, nil
}

func replaySessionPaths(fields map[string]json.RawMessage, from, to string) (map[string]json.RawMessage, error) {
	out := maps.Clone(fields)
	for key, raw := range fields {
		var value string
		if json.Unmarshal(raw, &value) != nil || !strings.HasPrefix(value, "/") {
			continue
		}
		if !strings.HasPrefix(value, from) {
			return nil, fmt.Errorf("%w: session path %q is outside its slot", ErrReplayConflict, value)
		}
		relative := strings.TrimPrefix(value, from)
		if relative == "" || path.Clean(relative) != relative || strings.HasPrefix(relative, "../") {
			return nil, fmt.Errorf("%w: invalid session path %q", ErrReplayConflict, value)
		}
		rewritten, err := json.Marshal(to + relative)
		if err != nil {
			return nil, fmt.Errorf("encode replay session path: %w", err)
		}
		out[key] = rewritten
	}
	return out, nil
}

func mergeReplayCheckpoint(ctx context.Context, repo *git.Repository, base, local, remote *replayCheckpoint, prefix string) (plumbing.Hash, error) {
	remoteExtra, err := replayExtraTree(repo, remote.extra)
	if err != nil {
		return plumbing.ZeroHash, err
	}
	extra, err := mergeReplayEntries(ctx, repo, base.extra, local.extra, remote.extra, remoteExtra, prefix)
	if err != nil {
		return plumbing.ZeroHash, err
	}
	entries, err := replayTreeEntries(repo, extra)
	if err != nil {
		return plumbing.ZeroHash, err
	}
	// Keep the remote's existing order, then append local-only identities. This
	// stays stable on retries even when the original clones used different slots.
	order := slices.Concat(remote.order, local.order, base.order)
	seen := make(map[string]bool)
	sessions := make([]map[string]json.RawMessage, 0)
	stats := make(map[string]object.TreeEntry)
	for _, sid := range order {
		if seen[sid] {
			continue
		}
		seen[sid] = true
		merged, mergeErr := mergeReplaySession(ctx, repo, base.sessions[sid], local.sessions[sid], remote.sessions[sid], path.Join(prefix, sid))
		if mergeErr != nil {
			return plumbing.ZeroHash, mergeErr
		}
		if merged.tree.IsZero() {
			continue
		}
		name := strconv.Itoa(len(sessions))
		fields, pathErr := replaySessionPaths(merged.fields, "/", "/"+path.Join(prefix, name)+"/")
		if pathErr != nil {
			return plumbing.ZeroHash, pathErr
		}
		sessions = append(sessions, fields)
		entries[name] = object.TreeEntry{Name: name, Mode: filemode.Dir, Hash: merged.tree}
		sessionEntries, readErr := replayTreeEntries(repo, merged.tree)
		if readErr != nil {
			return plumbing.ZeroHash, readErr
		}
		for file, entry := range sessionEntries {
			stats[path.Join(name, file)] = entry
		}
	}
	root, err := mergeReplaySummary(repo, base, local, remote, sessions, stats)
	if err != nil {
		return plumbing.ZeroHash, err
	}
	entries[paths.MetadataFileName] = object.TreeEntry{Name: paths.MetadataFileName, Mode: filemode.Regular, Hash: root}
	return replayExtraTree(repo, entries)
}

func replayExtraTree(repo *git.Repository, entries map[string]object.TreeEntry) (plumbing.Hash, error) {
	list := slices.Collect(maps.Values(entries))
	sortTreeEntries(list)
	return storeTree(repo, list)
}

func mergeReplaySession(ctx context.Context, repo *git.Repository, base, local, remote replaySession, name string) (replaySession, error) {
	entry := func(session replaySession) object.TreeEntry {
		if session.tree.IsZero() {
			return object.TreeEntry{}
		}
		return object.TreeEntry{Name: "session", Mode: filemode.Dir, Hash: session.tree}
	}
	merged, err := mergeReplayEntry(ctx, repo, entry(base), entry(local), entry(remote), name)
	if err != nil || merged.Mode == 0 {
		return replaySession{}, err
	}
	fields, err := mergeReplayJSON(base.fields, local.fields, remote.fields, name)
	if err != nil {
		return replaySession{}, err
	}
	if err := validateReplaySessionPaths(repo, merged.Hash, fields); err != nil {
		return replaySession{}, err
	}
	return replaySession{tree: merged.Hash, fields: fields}, nil
}

func mergeReplaySummary(repo *git.Repository, base, local, remote *replayCheckpoint, sessions []map[string]json.RawMessage, entries map[string]object.TreeEntry) (plumbing.Hash, error) {
	filtered := func(fields map[string]json.RawMessage) map[string]json.RawMessage {
		out := maps.Clone(fields)
		for _, key := range []string{"sessions", "checkpoints_count", "files_touched", "token_usage", "redaction", "has_review", "has_investigation", "imported", "linked_commits", "cli_version", "branch"} {
			delete(out, key)
		}
		return out
	}
	fields, err := mergeReplayJSON(filtered(base.fields), filtered(local.fields), filtered(remote.fields), "checkpoint metadata")
	if err != nil {
		return plumbing.ZeroHash, err
	}
	writer := &treeWriter{repo: repo}
	count, files, tokens, redaction, err := writer.reaggregateFromEntries("", len(sessions), entries)
	if err != nil {
		return plumbing.ZeroHash, err
	}
	values := map[string]any{
		"sessions": sessions, "checkpoints_count": count, "files_touched": files,
		"cli_version": versioninfo.Version,
	}
	// Keep the published checkpoint's branch context. Each merged session keeps
	// its own branch; replaying an older local generation must not oscillate
	// this display field or create a commit on every retry.
	if remote.summary.Branch != "" {
		values["branch"] = remote.summary.Branch
	}
	if tokens != nil {
		values["token_usage"] = tokens
	}
	if redaction != nil {
		values["redaction"] = redaction
	}
	for key, flag := range map[string]bool{
		"has_review":        local.summary.HasReview || remote.summary.HasReview,
		"has_investigation": local.summary.HasInvestigation || remote.summary.HasInvestigation,
		"imported":          local.summary.Imported || remote.summary.Imported,
	} {
		if flag {
			values[key] = true
		}
	}
	links, err := mergeReplayLinks(base, local, remote)
	if err != nil {
		return plumbing.ZeroHash, err
	}
	if len(links) > 0 {
		values["linked_commits"] = links
	}
	for key, value := range values {
		raw, marshalErr := json.Marshal(value)
		if marshalErr != nil {
			return plumbing.ZeroHash, fmt.Errorf("encode replay summary %s: %w", key, marshalErr)
		}
		fields[key] = raw
	}
	if replayJSONObjectEqual(fields, remote.fields) {
		return remote.metadata, nil
	}
	data, err := jsonutil.MarshalIndentWithNewline(fields, "", "  ")
	if err != nil {
		return plumbing.ZeroHash, fmt.Errorf("encode replay summary: %w", err)
	}
	return CreateBlobFromContent(repo, data)
}

func validateReplaySessionPaths(repo *git.Repository, hash plumbing.Hash, fields map[string]json.RawMessage) error {
	tree, err := repo.TreeObject(hash)
	if err != nil {
		return fmt.Errorf("read merged session: %w", err)
	}
	for _, raw := range fields {
		var name string
		if json.Unmarshal(raw, &name) != nil || !strings.HasPrefix(name, "/") {
			continue
		}
		if _, err := tree.FindEntry(strings.TrimPrefix(name, "/")); err != nil {
			return fmt.Errorf("merged session path %q: %w", name, err)
		}
	}
	return nil
}

func mergeReplayLinks(base, local, remote *replayCheckpoint) ([]map[string]json.RawMessage, error) {
	read := func(cp *replayCheckpoint) (map[string]map[string]json.RawMessage, error) {
		var list []map[string]json.RawMessage
		if raw := cp.fields["linked_commits"]; len(raw) > 0 {
			if err := json.Unmarshal(raw, &list); err != nil {
				return nil, fmt.Errorf("read checkpoint links: %w", err)
			}
		}
		out := make(map[string]map[string]json.RawMessage)
		for _, link := range list {
			var sha string
			if err := json.Unmarshal(link["sha"], &sha); err != nil {
				return nil, fmt.Errorf("read checkpoint link SHA: %w", err)
			}
			out[sha] = link
		}
		return out, nil
	}
	original, err := read(base)
	if err != nil {
		return nil, err
	}
	left, err := read(local)
	if err != nil {
		return nil, err
	}
	right, err := read(remote)
	if err != nil {
		return nil, err
	}
	links := unionLinkedCommits(remote.summary.LinkedCommits, local.summary.LinkedCommits)
	out := make([]map[string]json.RawMessage, 0, len(links))
	for _, link := range links {
		if left[link.SHA] == nil {
			out = append(out, right[link.SHA])
			continue
		}
		if right[link.SHA] == nil {
			out = append(out, left[link.SHA])
			continue
		}
		fields, err := mergeReplayJSON(original[link.SHA], left[link.SHA], right[link.SHA], "checkpoint link "+link.SHA)
		if err != nil {
			return nil, err
		}
		out = append(out, fields)
	}
	return out, nil
}
// recoverCheckpointRef replays exactly candidate.hash onto the fetched remote
// tip and installs the result only if the local ref still names that same
// generation. A concurrent checkpoint write therefore wins the CAS and remains
// both locally reachable and queued for a later delivery attempt.
func recoverCheckpointRef(
	ctx context.Context,
	repo *git.Repository,
	target string,
	candidate checkpointRefPush,
) (checkpointRefPush, error) {
	fetchTarget, err := remote.ResolveFetchTarget(ctx, target)
	if err != nil {
		return checkpointRefPush{}, fmt.Errorf("resolve fetch target: %w", err)
	}
	fetchedRefName := plumbing.ReferenceName(
		"refs/entire-fetch-tmp/" + strings.TrimPrefix(candidate.name.String(), "refs/"),
	)
	refSpec := fmt.Sprintf("+%s:%s", candidate.name, fetchedRefName)
	_, fetchSpan := perf.Start(ctx, "git_fetch")
	_, fetchErr := remote.Fetch(ctx, remote.FetchOptions{
		Remote:   fetchTarget,
		RefSpecs: []string{refSpec},
		NoTags:   true,
	})
	fetchSpan.RecordError(fetchErr)
	fetchSpan.End()
	if fetchErr != nil {
		return checkpointRefPush{}, fmt.Errorf("fetch failed: %w", fetchErr)
	}
	defer func() {
		_ = repo.Storer.RemoveReference(fetchedRefName) //nolint:errcheck // cleanup is best-effort
	}()

	// go-git loads a handle's pack index once and never reloads it, so objects
	// the fetch wrote into a new pack are invisible to a handle that has already
	// read objects. Replay from a freshly opened repository.
	repoPath, err := getRepoPath(repo)
	if err != nil {
		return checkpointRefPush{}, fmt.Errorf("get repository path: %w", err)
	}
	fetched, err := gitrepo.OpenPath(repoPath)
	if err != nil {
		return checkpointRefPush{}, fmt.Errorf("reopen repository after fetch: %w", err)
	}
	defer fetched.Close()

	remoteRef, err := fetched.Reference(fetchedRefName, true)
	if err != nil {
		return checkpointRefPush{}, fmt.Errorf("resolve fetched checkpoint ref: %w", err)
	}
	newTip, replayed, err := replayOntoRemote(ctx, fetched, candidate.hash, remoteRef.Hash())
	if err != nil {
		return checkpointRefPush{}, err
	}
	if err := checkpointRefRecoveryCAS(ctx, fetched, candidate.name, newTip, candidate.hash); err != nil {
		// newTip has no unique writer data: it is derived entirely from the
		// immutable candidate plus the fetched remote. On a CAS conflict the
		// writer's winning generation remains the live ref and its queue entry
		// remains untouched. A later delivery recomputes the replay from that
		// winner; retaining this losing intermediate under another ref would
		// create a second source of truth for the checkpoint.
		if errors.Is(err, gitrepo.ErrRefCASConflict) {
			err = fmt.Errorf("%w: %w", errCheckpointRefSuperseded, err)
		}
		return checkpointRefPush{}, fmt.Errorf("install recovered checkpoint ref %s: %w", candidate.name, err)
	}
	if replayed > 0 {
		// Recovery prints nothing on success, so the rewrite of local commits
		// must still leave a trace in the log. Metadata only.
		logging.Info(ctx, "replayed checkpoint ref onto fetched remote tip; local ref rewritten",
			slog.String("ref", candidate.name.String()),
			slog.String("local_tip", candidate.hash.String()),
			slog.String("remote_tip", remoteRef.Hash().String()),
			slog.Int("commits_replayed", replayed))
	}
	candidate.hash = newTip
	return candidate, nil
}

// replayOntoRemote returns the tip that results from replaying the commits
// only localHash reaches onto remoteHash. It never writes a ref; each caller
// installs the tip under its own update rule. Disconnected history (no merge
// base) is replayed with replayDisconnectedOnto. replayed counts the local
// commits handed to the cherry-pick, zero when the remote tip is returned as is.
func replayOntoRemote(
	ctx context.Context,
	repo *git.Repository,
	localHash, remoteHash plumbing.Hash,
) (tip plumbing.Hash, replayed int, err error) {
	if localHash.Equal(remoteHash) {
		return remoteHash, 0, nil
	}
	repoPath, err := getRepoPath(repo)
	if err != nil {
		return plumbing.ZeroHash, 0, fmt.Errorf("get repository path: %w", err)
	}
	mergeBase, err := getMergeBase(ctx, repoPath, localHash.String(), remoteHash.String())
	if err == nil && mergeBase.Equal(localHash) {
		return remoteHash, 0, nil
	}

	shallow, shallowErr := loadShallowHashes(ctx, repoPath)
	if shallowErr != nil {
		return plumbing.ZeroHash, 0, fmt.Errorf("load shallow boundaries: %w", shallowErr)
	}
	if errors.Is(err, errNoMergeBase) {
		tip, replayed, err := replayDisconnectedOnto(ctx, repo, localHash, remoteHash, shallow, io.Discard)
		if err != nil {
			return plumbing.ZeroHash, 0, fmt.Errorf("replay disconnected checkpoint commits: %w", err)
		}
		return tip, replayed, nil
	}
	if err != nil {
		return plumbing.ZeroHash, 0, fmt.Errorf("find checkpoint merge base: %w", err)
	}

	commits, err := collectCommitsSince(ctx, repo, repoPath, localHash, remoteHash)
	if err != nil {
		return plumbing.ZeroHash, 0, fmt.Errorf("collect local checkpoint commits: %w", err)
	}
	if len(commits) == 0 {
		return remoteHash, 0, nil
	}
	newTip, err := cherryPickOnto(ctx, repo, remoteHash, commits, shallow)
	if err != nil {
		return plumbing.ZeroHash, 0, fmt.Errorf("replay checkpoint commits: %w", err)
	}
	return newTip, len(commits), nil
}

